166	    private static final RowMapper<Pool> ROW = (rs, i) -> new Pool(rs.getLong("id"), rs.getString("sheet_id"),
167	            rs.getString("name"), rs.getString("added_by"));
168	
169	    private final JdbcTemplate jdbc;
