171	    public PoolRepository(JdbcTemplate jdbc) {
172	        this.jdbc = jdbc;
173	    }
174	
175	    /** The sheet's pools in the order they were added (those added by the end of the day, when one is given). */
176	    public List<Pool> list(String sheetId, LocalDate end) {
177	        return end == null
178	                ? jdbc.query("SELECT * FROM pool WHERE sheet_id = ? ORDER BY id", ROW, sheetId)
179	                : jdbc.query("SELECT * FROM pool WHERE sheet_id = ? AND (added_on IS NULL OR added_on <= ?) "
180	                        + "ORDER BY id", ROW, sheetId, end);
181	    }
182	
183	    /** The pool on this sheet with this name, or null when absent. */
184	    public Pool find(String sheetId, String name) {
185	        return jdbc.query("SELECT * FROM pool WHERE sheet_id = ? AND name = ?", ROW, sheetId, name).stream()
186	                .findFirst().orElse(null);
187	    }
188	
189	    /** The pool on this sheet with this id, or null when absent. */
190	    public Pool find(String sheetId, long id) {
191	        return jdbc.query("SELECT * FROM pool WHERE sheet_id = ? AND id = ?", ROW, sheetId, id).stream()
192	                .findFirst().orElse(null);
193	    }
194	
195	    public Pool add(String sheetId, PoolInput input) {
196	        jdbc.update("INSERT INTO pool (sheet_id, name, added_by, added_on) "
197	                + "VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", sheetId, input.name(), input.user(),
198	                sheetId);
199	        return find(sheetId, input.name());
200	    }
201	
202	    public boolean isMember(Pool pool, long personId) {
203	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool_member WHERE pool_id = ? AND person_id = ?",
204	                Integer.class, pool.id(), personId);
205	        return n != null && n > 0;
206	    }
207	
208	    /** The pool this pool is a member of, or null when it is a member of none. */
209	    public Pool parent(Pool pool) {
210	        return jdbc.query("SELECT p.* FROM pool p JOIN pool_member m ON m.pool_id = p.id WHERE m.member_pool_id = ?",
211	                ROW, pool.id()).stream().findFirst().orElse(null);
212	    }
213	
214	    /** The pools that are members of this pool. */
215	    public List<Pool> children(Pool pool) {
216	        return jdbc.query("SELECT p.* FROM pool p JOIN pool_member m ON m.member_pool_id = p.id WHERE m.pool_id = ? "
217	                + "ORDER BY m.id", ROW, pool.id());
218	    }
