220	    public PoolMember addMember(Pool pool, Pool member, PoolMemberInput input) {
221	        jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, member_pool_id, share, added_by, added_on) "
222	                + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", pool.sheetId(), pool.id(),
223	                member.id(), input.share(), input.user(), pool.sheetId());
224	        return new PoolMember(pool.id(), pool.sheetId(), pool.name(), 0, member.name(), input.share(), input.user(),
225	                member.id());
226	    }
227	
228	    public PoolMember addMember(Pool pool, Person person, PoolMemberInput input) {
229	        jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, person_id, share, added_by, added_on) "
230	                + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", pool.sheetId(), pool.id(),
231	                person.id(), input.share(), input.user(), pool.sheetId());
232	        return new PoolMember(pool.id(), pool.sheetId(), pool.name(), person.id(), person.name(), input.share(),
233	                input.user());
234	    }
