236	    /** The pool's members in the order they were added (those added by the end of the day, when one is given),
237	     *  named by the person's id (or the member pool's id) only: the caller names them. */
238	    public List<PoolMember> members(Pool pool, LocalDate end) {
239	        RowMapper<PoolMember> row = (rs, i) -> new PoolMember(pool.id(), pool.sheetId(), pool.name(),
240	                rs.getLong("person_id"), null, rs.getBigDecimal("share").setScale(2), rs.getString("added_by"),
241	                rs.getObject("member_pool_id", Long.class));
242	        return end == null
243	                ? jdbc.query("SELECT * FROM pool_member WHERE pool_id = ? ORDER BY id", row, pool.id())
244	                : jdbc.query("SELECT * FROM pool_member WHERE pool_id = ? AND (added_on IS NULL OR added_on <= ?) "
245	                        + "ORDER BY id", row, pool.id(), end);
246	    }
247	
248	    /** Drop the person from every pool they are a member of. */
249	    public void drop(String sheetId, long personId) {
250	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", sheetId, personId);
251	    }
252	
253	    /** On merging one person into another: the first's pool memberships move to the other, their share added to the
254	     *  other's where the other is already a member. */
255	    public void merge(String sheetId, long fromId, long intoId) {
256	        jdbc.update("UPDATE pool_member m SET share = share + (SELECT f.share FROM pool_member f WHERE f.pool_id = m.pool_id "
257	                + "AND f.person_id = ?) WHERE sheet_id = ? AND person_id = ? AND EXISTS (SELECT 1 FROM pool_member f "
258	                + "WHERE f.pool_id = m.pool_id AND f.person_id = ?)", fromId, sheetId, intoId, fromId);
259	        jdbc.update("DELETE FROM pool_member m WHERE sheet_id = ? AND person_id = ? AND EXISTS (SELECT 1 FROM pool_member i "
260	                + "WHERE i.pool_id = m.pool_id AND i.person_id = ?)", sheetId, fromId, intoId);
261	        jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
262	    }
263	}
