271	import java.math.BigDecimal;
272	import java.math.RoundingMode;
273	import java.util.ArrayList;
274	import java.time.LocalDate;
275	import java.util.List;
276	import java.util.Map;
277	import java.util.Set;
278	
279	/** A pool as the screen shows it: its members in the order they were added, the total of their shares (a member
280	 *  retired by the date counts 0.00) and whether it is balanced (the total is exactly 100.00). */
281	public record PoolResponse(long id, String name, List<Member> members, String totalShare, boolean balanced) {
282	
283	    /** A member: the person (or, for a member pool, null and the pool's id in poolId), their name, their share,
284	     *  whether they are retired by the date, and their cut of the pool's pot ('' when the pool is unbalanced or there
285	     *  is no pot). */
286	    public record Member(Long personId, String name, String share, boolean retired, String cut, Long poolId) {
287	    }
288	
289	    /** This member pool's cut, or null when it is not a member here or has no cut. */
290	    public BigDecimal cutOf(long memberPoolId) {
291	        return members.stream().filter(m -> m.poolId() != null && m.poolId() == memberPoolId && !m.cut().isEmpty())
292	                .map(m -> new BigDecimal(m.cut())).findFirst().orElse(null);
293	    }
294	
295	    private static final BigDecimal FULL = new BigDecimal("100.00");
296	
297	    /** The pool with its members; retiredFrom gives each person's retirement date (absent: not retired), held the
298	     *  people with a hold in force on the date, and on is the date it is judged by (null: none retired). When the
299	     *  pool is balanced and there is a pot (null: none), a retired or held member cuts 0.00 and each other member's
300	     *  cut is the pot (the sheet's, or for a member pool its cut in the pool above) times their share divided by the
301	     *  shares of the members with a cut, added up, rounded half to even to two decimals, and the pot less the cuts
302	     *  goes to the member with a cut with the largest share (the earliest added on a tie), so the cuts total exactly
303	     *  the pot. A hold leaves the total share and balance alone. */
304	    public static PoolResponse from(Pool pool, List<PoolMember> members, Map<Long, LocalDate> retiredFrom,
305	            Set<Long> held, LocalDate on, BigDecimal pot) {
306	        BigDecimal total = BigDecimal.ZERO.setScale(2);
307	        boolean[] retired = new boolean[members.size()];
308	        for (int i = 0; i < members.size(); i++) {
309	            PoolMember m = members.get(i);
310	            LocalDate from = m.isPool() ? null : retiredFrom.get(m.personId());
311	            retired[i] = on != null && from != null && !from.isAfter(on);
312	            if (!retired[i]) {
313	                total = total.add(m.share());
314	            }
315	        }
316	        boolean balanced = total.compareTo(FULL) == 0;
317	        boolean[] noCut = new boolean[members.size()];
318	        for (int i = 0; i < members.size(); i++) {
319	            PoolMember m = members.get(i);
320	            noCut[i] = retired[i] || (!m.isPool() && held.contains(m.personId()));
321	        }
322	        BigDecimal[] cuts = balanced && pot != null ? cuts(members, noCut, pot) : null;
323	        List<Member> shown = new ArrayList<>();
324	        for (int i = 0; i < members.size(); i++) {
325	            PoolMember m = members.get(i);
326	            shown.add(new Member(m.isPool() ? null : m.personId(), m.name(), m.share().toPlainString(), retired[i],
327	                    cuts != null ? cuts[i].toPlainString() : "", m.memberPoolId()));
328	        }
329	        return new PoolResponse(pool.id(), pool.name(), shown, total.toPlainString(), balanced);
330	    }
331	
332	    public static PoolResponse from(Pool pool, List<PoolMember> members, LocalDate on) {
333	        return from(pool, members, Map.of(), Set.of(), on, null);
334	    }
335	
336	    private static BigDecimal[] cuts(List<PoolMember> members, boolean[] noCut, BigDecimal pot) {
337	        BigDecimal[] cuts = new BigDecimal[members.size()];
338	        BigDecimal shares = BigDecimal.ZERO;
339	        for (int i = 0; i < members.size(); i++) {
340	            if (!noCut[i]) {
341	                shares = shares.add(members.get(i).share());
342	            }
343	        }
344	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
345	        int largest = -1;
346	        for (int i = 0; i < members.size(); i++) {
347	            BigDecimal share = members.get(i).share();
348	            cuts[i] = noCut[i] ? BigDecimal.ZERO.setScale(2)
349	                    : pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN);
350	            sum = sum.add(cuts[i]);
351	            if (!noCut[i] && (largest < 0 || share.compareTo(members.get(largest).share()) > 0)) {
352	                largest = i;
353	            }
354	        }
355	        if (largest >= 0) {
356	            cuts[largest] = cuts[largest].add(pot.subtract(sum));
357	        }
358	        return cuts;
359	    }
360	}
