400	
401	/** The sheet's pools in the order they were added, with their members, total share and whether balanced; a member
402	 *  retired by the sheet's today (or the as-of date, when one is given) counts 0.00 toward the total; each member of a balanced pool
403	 *  shows their cut of the pool's pot (when there is one). A pool that is a member of none has the sheet's pot; a pool
404	 *  that is a member of another has its cut there as its pot (none when the pool above has no cuts). A person with a
405	 *  hold in force on that date cuts 0.00, their share spread over the members with a cut. */
406	public class RespondWithPools {
407	    public void respond(@PathVariable("sheetId") String sheetId,
408	            @RequestParam(name = "asOf", required = false) String asOf, PoolRepository repository,
409	            PersonRepository people, SheetRepository sheets, SettingRepository settings,
410	            ObjectResponse<List<PoolResponse>> response) {
411	        String id = sheetId.trim();
412	        LocalDate end = AsOf.parse(asOf);
413	        LocalDate on = end != null ? end : sheets.today(id);
414	        List<Person> persons = end != null ? people.listAsOf(id, end) : people.list(id);
415	        Map<Long, LocalDate> retiredFrom = new HashMap<>();
416	        Map<Long, String> names = new HashMap<>();
417	        Set<Long> held = new HashSet<>();
418	        BigDecimal pot = settings.pot(id);
419	        for (Person p : persons) {
420	            names.put(p.id(), p.name());
421	            if (p.retiredFrom() != null) {
422	                retiredFrom.put(p.id(), p.retiredFrom());
423	            }
424	            if (on != null && p.holds().covers(on)) {
425	                held.add(p.id());
426	            }
427	        }
428	        List<Pool> pools = repository.list(id, end);
429	        Map<Long, String> poolNames = new HashMap<>();
430	        pools.forEach(p -> poolNames.put(p.id(), p.name()));
431	        Map<Long, List<PoolMember>> members = new HashMap<>();
432	        Map<Long, Pool> parents = new HashMap<>();
433	        for (Pool pool : pools) {
434	            List<PoolMember> named = repository.members(pool, end).stream()
435	                    .filter(m -> m.isPool() ? poolNames.containsKey(m.memberPoolId())
436	                            : names.containsKey(m.personId()))
437	                    .map(m -> new PoolMember(m.poolId(), m.sheetId(), m.pool(), m.personId(),
438	                            m.isPool() ? poolNames.get(m.memberPoolId()) : names.get(m.personId()), m.share(),
439	                            m.by(), m.memberPoolId()))
440	                    .toList();
441	            members.put(pool.id(), named);
442	            named.stream().filter(PoolMember::isPool).forEach(m -> parents.put(m.memberPoolId(), pool));
443	        }
444	        Map<Long, PoolResponse> shown = new HashMap<>();
445	        response.send(pools.stream()
446	                .map(pool -> shown(pool, members, parents, retiredFrom, held, on, pot, shown)).toList());
447	    }
448	
449	    /** The pool as shown, its pot the sheet's or its cut in the pool above (worked out first). */
450	    private static PoolResponse shown(Pool pool, Map<Long, List<PoolMember>> members, Map<Long, Pool> parents,
451	            Map<Long, LocalDate> retiredFrom, Set<Long> held, LocalDate on, BigDecimal sheetPot, Map<Long, PoolResponse> shown) {
452	        PoolResponse done = shown.get(pool.id());
453	        if (done != null) {
454	            return done;
455	        }
456	        Pool above = parents.get(pool.id());
457	        BigDecimal pot = above == null ? sheetPot
458	                : shown(above, members, parents, retiredFrom, held, on, sheetPot, shown).cutOf(pool.id());
459	        PoolResponse r = PoolResponse.from(pool, members.get(pool.id()), retiredFrom, held, on, pot);
460	        shown.put(pool.id(), r);
461	        return r;
462	    }
463	}
