492	/** Store the member, refusing an unknown pool or person, or a person already in the pool. A member pool is refused
493	 *  when it is already a member of a pool, when it is the pool itself or contains it through any chain, or when the
494	 *  chain of pools would be more than three deep. */
495	public class SavePoolMember {
496	    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("poolId") String poolId,
497	            @Val PoolMemberInput input, PeriodRepository periods, PoolRepository repository, PersonRepository people,
498	            Out<PoolMember> member) throws InvalidPoolException {
499	        String id = sheetId.trim();
500	        periods.lockSheet(id);
501	        Pool pool;
502	        try {
503	            pool = repository.find(id, Long.parseLong(poolId.trim()));
504	        } catch (NumberFormatException e) {
505	            pool = null;
506	        }
507	        if (pool == null) {
508	            throw new InvalidPoolException("No pool " + poolId + " on this sheet.");
509	        }
510	        if (input.memberPoolId() != null) {
511	            member.set(repository.addMember(pool, memberPool(id, pool, input.memberPoolId(), repository), input));
512	            return;
513	        }
514	        Person person = people.find(id, input.personId());
515	        if (person == null) {
516	            throw new InvalidPoolException("No person " + input.personId() + " on this sheet.");
517	        }
518	        if (repository.isMember(pool, person.id())) {
519	            throw new InvalidPoolException(person.name() + " is already in " + pool.name() + ".");
520	        }
521	        member.set(repository.addMember(pool, person, input));
522	    }
523	
524	    private static final int MAX_DEPTH = 3;
525	
526	    private static Pool memberPool(String sheetId, Pool pool, long memberPoolId, PoolRepository repository)
527	            throws InvalidPoolException {
528	        Pool child = repository.find(sheetId, memberPoolId);
529	        if (child == null) {
530	            throw new InvalidPoolException("No pool " + memberPoolId + " on this sheet.");
531	        }
532	        if (child.id() == pool.id()) {
533	            throw new InvalidPoolException("A pool cannot be a member of itself.");
534	        }
535	        Pool above = repository.parent(child);
536	        if (above != null) {
537	            throw new InvalidPoolException(child.name() + " is already a member of " + above.name() + ".");
538	        }
539	        int depth = 1;
540	        for (Pool p = repository.parent(pool); p != null; p = repository.parent(p)) {
541	            if (p.id() == child.id()) {
542	                throw new InvalidPoolException(pool.name() + " is already within " + child.name() + ".");
543	            }
544	            depth++;
545	        }
546	        if (depth + height(child, repository) > MAX_DEPTH) {
547	            throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep.");
548	        }
549	        return child;
550	    }
551	
552	    /** How many levels of pools this pool heads, itself included. */
553	    private static int height(Pool pool, PoolRepository repository) {
554	        int below = 0;
555	        for (Pool c : repository.children(pool)) {
556	            below = Math.max(below, height(c, repository));
557	        }
558	        return below + 1;
559	    }
560	}
