865	/** A person's cuts, in cents, across every pool they are a member of (a pool showing no cut adds nothing). */
866	function personCutCents(pools: Pool[], personId: number): number {
867	  return pools
868	    .flatMap((p) => p.members)
869	    .filter((m) => m.poolId === null && m.personId === personId && m.cut !== '')
870	    .reduce((total, m) => total + cents(m.cut), 0);
871	}
