#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
for i in $(seq 1 60); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
  sleep 1
done

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
  test("pool membership dated scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-20");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "clerk-limit", "3.00");
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "late-pct", "10.00");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "grace-days", "3");
    await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
    expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
    await ui.setSetting(pg_uma, "grace-B", "2");
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "1.00", "note": "tpl"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00", "from": "2026-03-01", "to": "2026-03-25"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "contact": "ben@x"}));
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.unstate(pg_vic, p_ben)).toBe(true);
    expect(await ui.periodAction(pg_vic, "P1", "soft-close")).toBe(true);
    const c_dot_0 = ui.must(await ui.quickAdd(pg_vic, {"name": "Dot", "amount": "3.33"}));
    const p_dot = await ui.personId(pg_vic, "Dot");
    await ui.refresh(pg_vic);
    expect(await ui.merge(pg_vic, p_cam, "Ben")).toBe(true);
    const c_ben_0 = ui.must(await ui.quickAdd(pg_vic, {"name": "Ben", "amount": "10.25"}));
    expect(await ui.addAlias(pg_vic, p_dot, "Al")).toBe(true);
    await ui.refresh(pg_vic);
    await ui.refresh(pg_vic);
    expect(await ui.merge(pg_vic, p_dot, "Ben")).toBe(true);
    const c_ben_1 = await ui.claimAt(pg_vic, p_ben, 1);
    const c_ben_2 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "10.25", "date": "2026-03-15", "note": "n"}));
    expect(await ui.statement(pg_vic, p_ben)).toBe(true);
    expect(await ui.statement(pg_vic, p_ben)).toBe(true);
    expect(await ui.periodAction(pg_vic, "P2", "soft-close")).toBe(true);
    expect(await ui.addComment(pg_vic, c_ben_2, "ok")).toBe(true);
    expect(await ui.statementAsOf(pg_vic, p_ben, "2026-03-01")).toBe(false);
    await ui.refresh(pg_vic);

